package {{packageName}};

import net.fabricmc.api.ModInitializer;
import net.minecraft.resources.ResourceLocation;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class {{mainClassSimpleName}} implements ModInitializer {
	public static final String MOD_ID = "{{modId}}";
	public static final Logger LOGGER = LoggerFactory.getLogger(MOD_ID);

	@Override
	public void onInitialize() {
		{{mainClassSimpleName}}Items.init();
		{{mainClassSimpleName}}Blocks.init();
{{REGISTRY_INIT_CALLS}}
		LOGGER.info("{} initialized for Minecraft {{mcVersion}}", MOD_ID);
	}

	/** Namespaced id helper (1.21+ API: ResourceLocation.fromNamespaceAndPath). */
	public static ResourceLocation id(String path) {
		return new ResourceLocation(MOD_ID, path);
	}
}

